    this->p_02_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->p_03_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->p_04_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->p_05_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->p_06_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->ctlin_40_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->ctlin_41_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->ctlin_42_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->ctlin_43_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->ctlin_44_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->ctlin_45_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->ctlin_46_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->ctlin_47_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->ctlin_48_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
    this->ctlin_49_midihandler(data[0] & 240, (data[0] & 15) + 1, port, data, length);
