    ParameterValue applyStepsToNormalizedParameterValue(ParameterValue normalizedValue, int steps) const {
        if (steps == 1) {
            if (normalizedValue > 0) {
                normalizedValue = 1.;
            }
        } else {
            ParameterValue oneStep = (number)1. / (steps - 1);
            ParameterValue numberOfSteps = rnbo_fround(normalizedValue / oneStep * 1 / (number)1) * (number)1;
            normalizedValue = numberOfSteps * oneStep;
        }
    
        return normalizedValue;
    }
    
    ParameterValue convertToNormalizedParameterValue(ParameterIndex index, ParameterValue value) const {
        switch (index) {
        case 2:
        case 3:
        case 5:
        case 6:
            {
            {
                value = (value < 0 ? 0 : (value > 1 ? 1 : value));
                ParameterValue normalizedValue = (value - 0) / (1 - 0);
                return normalizedValue;
            }
            }
        case 1:
            {
            {
                value = (value < 0 ? 0 : (value > 5 ? 5 : value));
                ParameterValue normalizedValue = (value - 0) / (5 - 0);
                return normalizedValue;
            }
            }
        case 4:
            {
            {
                value = (value < 0 ? 0 : (value > 10 ? 10 : value));
                ParameterValue normalizedValue = (value - 0) / (10 - 0);
                return normalizedValue;
            }
            }
        case 0:
            {
            {
                value = (value < 0.1 ? 0.1 : (value > 60 ? 60 : value));
                ParameterValue normalizedValue = (value - 0.1) / (60 - 0.1);
                return normalizedValue;
            }
            }
        default:
            {
            return value;
            }
        }
    }
    
    ParameterValue convertFromNormalizedParameterValue(ParameterIndex index, ParameterValue value) const {
        value = (value < 0 ? 0 : (value > 1 ? 1 : value));
    
        switch (index) {
        case 2:
        case 3:
        case 5:
        case 6:
            {
            {
                {
                    return 0 + value * (1 - 0);
                }
            }
            }
        case 1:
            {
            {
                {
                    return 0 + value * (5 - 0);
                }
            }
            }
        case 4:
            {
            {
                {
                    return 0 + value * (10 - 0);
                }
            }
            }
        case 0:
            {
            {
                {
                    return 0.1 + value * (60 - 0.1);
                }
            }
            }
        default:
            {
            return value;
            }
        }
    }
    
