template<typename LISTTYPE> void codebox_08_in1_set(const LISTTYPE& in1) {
    this->codebox_08_in1 = jsCreateListCopy(in1);
    this->codebox_08_flatness = this->codebox_08_in1[0];//#map:codebox_obj-82:22
    this->codebox_08_centroid = this->codebox_08_in1[1];//#map:codebox_obj-82:23
    this->codebox_08_flatness_cutoff_set(this->codebox_08_in2);//#map:codebox_obj-82:24
    this->codebox_08_centroid_cutoff_set(this->codebox_08_in3);//#map:codebox_obj-82:25
    number flatness_is_kick = 0;
    number centroid_is_kick = 0;

    if (this->codebox_08_flatness < this->codebox_08_flatness_cutoff) {
        flatness_is_kick = 1;//#map:_###_obj_###_:29
    }//#map:codebox_obj-82:29

    if (this->codebox_08_centroid < this->codebox_08_centroid_cutoff) {
        centroid_is_kick = 1;//#map:_###_obj_###_:30
    }//#map:codebox_obj-82:30

    number is_kick = 0;

    if (flatness_is_kick == 1 && centroid_is_kick == 1) {
        is_kick = 1;//#map:_###_obj_###_:35
    } else if (flatness_is_kick == 0 && centroid_is_kick == 0) {
        is_kick = 0;//#map:_###_obj_###_:37
    } else {
        number conf_flat = this->codebox_08_zone_confidence(this->codebox_08_flatness, this->codebox_08_flatness_cutoff, 0, 1);
        number conf_cent = this->codebox_08_zone_confidence(this->codebox_08_centroid, this->codebox_08_centroid_cutoff, 0, 10000);

        this->post(
            ">>>>>> CONFLICT | conf_flat=",
            conf_flat,
            " | conf_cent=",
            conf_cent,
            "<<<<<<"
        );//#map:_###_obj_###_:42

        if (conf_flat >= conf_cent) {
            is_kick = flatness_is_kick;//#map:_###_obj_###_:44
        } else {
            is_kick = centroid_is_kick;//#map:_###_obj_###_:46
        }//#map:_###_obj_###_:43
    }//#map:_###_obj_###_:36//#map:codebox_obj-82:34

    if (this->codebox_08_invert_output == 1) {
        if (is_kick == 1) {
            this->post(">>>>> inverted_SNARE | kick detected | ", this->_currentTime, "<<<<<");//#map:_###_obj_###_:52
            this->codebox_08_out1_set(0);//#map:_###_obj_###_:53
            this->codebox_08_out2_set(1);//#map:_###_obj_###_:54
        } else {
            this->post(">>>>> inverted_KICK | snare detected | ", this->_currentTime, "<<<<<");//#map:_###_obj_###_:56
            this->codebox_08_out1_set(1);//#map:_###_obj_###_:57
            this->codebox_08_out2_set(0);//#map:_###_obj_###_:58
        }//#map:_###_obj_###_:51
    } else {
        if (is_kick == 1) {
            this->post(">>>>> KICK | ", this->_currentTime, "<<<<<");//#map:_###_obj_###_:62
            this->codebox_08_out1_set(1);//#map:_###_obj_###_:63
            this->codebox_08_out2_set(0);//#map:_###_obj_###_:64
        } else {
            this->post(">>>>> SNARE | ", this->_currentTime, "<<<<<");//#map:_###_obj_###_:66
            this->codebox_08_out1_set(0);//#map:_###_obj_###_:67
            this->codebox_08_out2_set(1);//#map:_###_obj_###_:68
        }//#map:_###_obj_###_:61
    }//#map:codebox_obj-82:50

    this->post(
        ">>>>>> flatness=",
        this->codebox_08_flatness,
        " | centroid=",
        this->codebox_08_centroid,
        "<<<<<<"
    );//#map:codebox_obj-82:72
}

