number codebox_08_zone_confidence(number value, number cutoff, number min_val, number max_val) /*#map:_###_obj_###_:9*/
{
    number zone_width;

    if (value < cutoff) {
        zone_width = cutoff - min_val;//#map:_###_obj_###_:12
    } else {
        zone_width = max_val - cutoff;//#map:_###_obj_###_:14
    }//#map:_###_obj_###_:11

    if (zone_width <= 0) {
        return 0;//#map:_###_obj_###_:17
    }//#map:_###_obj_###_:16

    return (zone_width == 0. ? 0. : rnbo_abs(value - cutoff) / zone_width);//#map:_###_obj_###_:19
}

